pub const Complex = std.math.Complex;

pub const EdgeQuality = enum(u8) {
    superposition = 0,
    entangled = 1,
    coherent = 2,
    collapsed = 3,
    fractal = 4,
};

pub const Node = struct {
    id: []const u8,
    type_name: []const u8,
    data: []const u8,
    quantum_state: Complex(f64),
    phase: f64,
    fractal_dimension: f64,
    allocator: Allocator,

    pub fn init(allocator: Allocator, id: []const u8, type_name: []const u8, real: f64, imag: f64, phase: f64) !Node {
        return Node{
            .id = try allocator.dupe(u8, id),
            .type_name = try allocator.dupe(u8, type_name),
            .data = try allocator.dupe(u8, ""),
            .quantum_state = Complex(f64).init(real, imag),
            .phase = phase,
            .fractal_dimension = 1.0,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Node) void {
        self.allocator.free(self.id);
        self.allocator.free(self.type_name);
        self.allocator.free(self.data);
    }

    pub fn clone(self: *const Node, allocator: Allocator) !Node {
        return Node{
            .id = try allocator.dupe(u8, self.id),
            .type_name = try allocator.dupe(u8, self.type_name),
            .data = try allocator.dupe(u8, self.data),
            .quantum_state = self.quantum_state,
            .phase = self.phase,
            .fractal_dimension = self.fractal_dimension,
            .allocator = allocator,
        };
    }

    pub fn magnitude(self: *const Node) f64 {
        return self.quantum_state.magnitude();
    }

    pub fn probability(self: *const Node) f64 {
        const mag = self.quantum_state.magnitude();
        return mag * mag;
    }
};

pub const EdgeKey = struct {
    source: []const u8,
    target: []const u8,

    pub fn hash(self: EdgeKey) u64 {
        var hasher = std.hash.Wyhash.init(0);
        hasher.update(self.source);
        hasher.update(self.target);
        return hasher.final();
    }

    pub fn eql(a: EdgeKey, b: EdgeKey) bool {
        return std.mem.eql(u8, a.source, b.source) and std.mem.eql(u8, a.target, b.target);
    }
};

pub const EdgeKeyContext = struct {
    pub fn hash(_: @This(), key: EdgeKey) u64 {
        return key.hash();
    }

    pub fn eql(_: @This(), a: EdgeKey, b: EdgeKey) bool {
        return EdgeKey.eql(a, b);
    }
};

