pub const SelfSimilarRelationalGraph = struct {
    nodes: StringHashMap(Node),
    edges: std.HashMap(EdgeKey, ArrayList(Edge), EdgeKeyContext, std.hash_map.default_max_load_percentage),
    quantum_register: StringHashMap(Complex(f64)),
    fractal_depth: usize,
    topology_hash: [32]u8,
    allocator: Allocator,

    pub fn init(allocator: Allocator) SelfSimilarRelationalGraph {
        return SelfSimilarRelationalGraph{
            .nodes = StringHashMap(Node).init(allocator),
            .edges = std.HashMap(EdgeKey, ArrayList(Edge), EdgeKeyContext, std.hash_map.default_max_load_percentage).init(allocator),
            .quantum_register = StringHashMap(Complex(f64)).init(allocator),
            .fractal_depth = 0,
            .topology_hash = [_]u8{0} ** 32,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *SelfSimilarRelationalGraph) void {
        var node_iter = self.nodes.iterator();
        while (node_iter.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            var node = entry.value_ptr;
            node.deinit();
        }
        self.nodes.deinit();

        var edge_iter = self.edges.iterator();
        while (edge_iter.next()) |entry| {
            for (entry.value_ptr.items) |*edge| {
                edge.deinit();
            }
            entry.value_ptr.deinit();
        }
        self.edges.deinit();

        var qr_iter = self.quantum_register.iterator();
        while (qr_iter.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
        }
        self.quantum_register.deinit();
    }

    pub fn addNode(self: *SelfSimilarRelationalGraph, node: Node) !void {
        const key = try self.allocator.dupe(u8, node.id);
        try self.nodes.put(key, node);
        try self.setQuantumState(node.id, node.quantum_state);
    }

    pub fn hasNode(self: *const SelfSimilarRelationalGraph, id: []const u8) bool {
        return self.nodes.contains(id);
    }

    pub fn getNode(self: *SelfSimilarRelationalGraph, id: []const u8) ?*Node {
        return self.nodes.getPtr(id);
    }

    pub fn nodeCount(self: *const SelfSimilarRelationalGraph) usize {
        return self.nodes.count();
    }

    pub fn addEdge(self: *SelfSimilarRelationalGraph, edge: Edge) !void {
        const key = EdgeKey{ .source = edge.source, .target = edge.target };
        const result = try self.edges.getOrPut(key);
        if (!result.found_existing) {
            result.value_ptr.* = ArrayList(Edge).init(self.allocator);
        }
        try result.value_ptr.append(edge);
    }

    pub fn hasEdge(self: *const SelfSimilarRelationalGraph, source: []const u8, target: []const u8) bool {
        const key = EdgeKey{ .source = source, .target = target };
        return self.edges.contains(key);
    }

    pub fn getEdges(self: *SelfSimilarRelationalGraph, source: []const u8, target: []const u8) ?*ArrayList(Edge) {
        const key = EdgeKey{ .source = source, .target = target };
        return self.edges.getPtr(key);
    }

    pub fn getEdgeList(self: *const SelfSimilarRelationalGraph, source: []const u8, target: []const u8) []const Edge {
        const key = EdgeKey{ .source = source, .target = target };
        if (self.edges.getPtr(key)) |list| {
            return list.items;
        }
        return &[_]Edge{};
    }

    pub fn edgeCount(self: *const SelfSimilarRelationalGraph) usize {
        var count: usize = 0;
        var iter = self.edges.valueIterator();
        while (iter.next()) |list| {
            count += list.items.len;
        }
        return count;
    }

    pub fn setQuantumState(self: *SelfSimilarRelationalGraph, node_id: []const u8, state: Complex(f64)) !void {
        const key = try self.allocator.dupe(u8, node_id);
        try self.quantum_register.put(key, state);
    }

    pub fn applyQuantumGate(self: *SelfSimilarRelationalGraph, node_id: []const u8, gate: fn (Complex(f64)) Complex(f64)) void {
        if (self.nodes.getPtr(node_id)) |node| {
            node.quantum_state = gate(node.quantum_state);
            self.setQuantumState(node_id, node.quantum_state) catch return;
        }
    }

    pub fn entangleNodes(self: *SelfSimilarRelationalGraph, node1: []const u8, node2: []const u8) !void {
        const n1 = self.getNode(node1) orelse return error.NodeNotFound;
        const n2 = self.getNode(node2) orelse return error.NodeNotFound;

        const avg_real = (n1.quantum_state.re + n2.quantum_state.re) / 2.0;
        const avg_imag = (n1.quantum_state.im + n2.quantum_state.im) / 2.0;
        const entangled_state = Complex(f64).init(avg_real, avg_imag);

        n1.quantum_state = entangled_state;
        n2.quantum_state = entangled_state;

        try self.setQuantumState(node1, entangled_state);
        try self.setQuantumState(node2, entangled_state);

        if (self.hasEdge(node1, node2)) {
            if (self.getEdges(node1, node2)) |edges| {
                for (edges.items) |*edge| {
                    edge.quality = .entangled;
                }
            }
        } else {
            const edge = try Edge.init(self.allocator, node1, node2, .entangled, 1.0, avg_real, avg_imag, 1.0);
            try self.addEdge(edge);
        }
    }

    pub fn measure(self: *SelfSimilarRelationalGraph, node_id: []const u8) f64 {
        if (self.getNode(node_id)) |node| {
            const prob = node.probability();
            node.quantum_state = Complex(f64).init(if (prob > 0.5) 1.0 else 0.0, 0.0);
            self.setQuantumState(node_id, node.quantum_state) catch return prob;
            return prob;
        }
        return 0.0;
    }

    pub fn calculateFractalDimension(self: *const SelfSimilarRelationalGraph) f64 {
        if (self.nodeCount() == 0) return 0.0;
        const n = @as(f64, @floatFromInt(self.nodeCount()));
        const e = @as(f64, @floatFromInt(self.edgeCount()));
        if (n <= 1.0) return 1.0;
        return @log(e + 1.0) / @log(n);
    }

    pub fn getTopologyHashHex(self: *const SelfSimilarRelationalGraph) []const u8 {
        var hex: [64]u8 = undefined;
        const chars = "0123456789abcdef";
        for (self.topology_hash, 0..) |byte, i| {
            hex[i * 2] = chars[byte >> 4];
            hex[i * 2 + 1] = chars[byte & 0x0F];
        }
        return &hex;
    }

    pub fn encodeInformation(self: *SelfSimilarRelationalGraph, data: []const u8) ![]const u8 {
        var hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(data, &hash, .{});

        var node_id = try std.fmt.allocPrint(self.allocator, "info_{x}", .{hash[0..8].*});
        var node = try Node.init(self.allocator, node_id, "information", 1.0, 0.0, 0.0);
        self.allocator.free(node.data);
        node.data = try self.allocator.dupe(u8, data);
        try self.addNode(node);

        return node_id;
    }

    pub fn decodeInformation(self: *SelfSimilarRelationalGraph, node_id: []const u8) ?[]const u8 {
        if (self.getNode(node_id)) |node| {
            return node.data;
        }
        return null;
    }

    pub fn clear(self: *SelfSimilarRelationalGraph) void {
        var node_iter = self.nodes.iterator();
        while (node_iter.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            var node = entry.value_ptr;
            node.deinit();
        }
        self.nodes.clearRetainingCapacity();

        var edge_iter = self.edges.iterator();
        while (edge_iter.next()) |entry| {
            for (entry.value_ptr.items) |*edge| {
                edge.deinit();
            }
            entry.value_ptr.deinit();
        }
        self.edges.clearRetainingCapacity();

        var qr_iter = self.quantum_register.iterator();
        while (qr_iter.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
        }
        self.quantum_register.clearRetainingCapacity();
    }
};

pub fn hadamardGate(state: Complex(f64)) Complex(f64) {
    const inv_sqrt2 = 1.0 / @sqrt(2.0);
    return Complex(f64).init((state.re + state.im) * inv_sqrt2, (state.re - state.im) * inv_sqrt2);
}

pub fn pauliXGate(state: Complex(f64)) Complex(f64) {
    return Complex(f64).init(state.im, state.re);
}

pub fn pauliYGate(state: Complex(f64)) Complex(f64) {
    return Complex(f64).init(-state.im, state.re);
}

pub fn pauliZGate(state: Complex(f64)) Complex(f64) {
    return Complex(f64).init(state.re, -state.im);
}

pub fn identityGate(state: Complex(f64)) Complex(f64) {
    return state;
}
