const StringHashMap = std.StringHashMap;

pub const SignalTrace = struct {
    node_id: []const u8,
    timestamp: i64,
    amplitude: f64,
    phase: f64,
    allocator: Allocator,

    pub fn init(allocator: Allocator, node_id: []const u8, amplitude: f64, phase: f64) !SignalTrace {
