pub const SignalPropagationEngine = struct {
    allocator: Allocator,
    graph: *nsir.SelfSimilarRelationalGraph,
    traces: ArrayList(SignalTrace),
    time_step: f64,
    damping_factor: f64,
    propagation_speed: f64,

    pub fn init(allocator: Allocator, graph: *nsir.SelfSimilarRelationalGraph) SignalPropagationEngine {
        return SignalPropagationEngine{
            .allocator = allocator,
            .graph = graph,
            .traces = ArrayList(SignalTrace).init(allocator),
            .time_step = 0.01,
            .damping_factor = 0.98,
            .propagation_speed = 1.0,
        };
    }

    pub fn deinit(self: *SignalPropagationEngine) void {
        for (self.traces.items) |*trace| {
            trace.deinit();
        }
        self.traces.deinit();
    }

    pub fn setParameters(self: *SignalPropagationEngine, time_step: f64, damping: f64, speed: f64) void {
        self.time_step = time_step;
        self.damping_factor = damping;
        self.propagation_speed = speed;
    }

    pub fn propagateSignal(self: *SignalPropagationEngine, source_id: []const u8, initial_amplitude: f64) !void {
        if (self.graph.getNode(source_id)) |source_node| {
            const trace = try SignalTrace.init(self.allocator, source_id, initial_amplitude, source_node.phase);
            try self.traces.append(trace);

            var visited = StringHashMap(bool).init(self.allocator);
            defer visited.deinit();
            try visited.put(source_id, true);

            var current_wave = ArrayList([]const u8).init(self.allocator);
            defer {
                for (current_wave.items) |node_id| {
                    self.allocator.free(node_id);
                }
                current_wave.deinit();
            }

            try current_wave.append(try self.allocator.dupe(u8, source_id));

            var wave_amplitude = initial_amplitude;
            var steps: usize = 0;
            const max_steps: usize = 100;

            while (current_wave.items.len > 0 and steps < max_steps) : (steps += 1) {
                var next_wave = ArrayList([]const u8).init(self.allocator);
                defer {
                    for (next_wave.items) |node_id| {
                        self.allocator.free(node_id);
                    }
                    next_wave.deinit();
                }

                wave_amplitude *= self.damping_factor;

                for (current_wave.items) |current_id| {
                    var edge_iter = self.graph.edges.iterator();
                    while (edge_iter.next()) |entry| {
                        const key = entry.key_ptr;
                        if (std.mem.eql(u8, key.source, current_id)) {
                            const target_id = key.target;
                            if (!visited.contains(target_id)) {
                                if (self.graph.getNode(target_id)) |target_node| {
                                    const phase_shift = self.time_step * self.propagation_speed;
                                    target_node.phase = @mod(target_node.phase + phase_shift, 2.0 * std.math.pi);

                                    const new_real = target_node.quantum_state.re + wave_amplitude * @cos(target_node.phase);
                                    const new_imag = target_node.quantum_state.im + wave_amplitude * @sin(target_node.phase);
                                    target_node.quantum_state = nsir.Complex(f64).init(new_real, new_imag);

                                    try self.graph.setQuantumState(target_id, target_node.quantum_state);

                                    const target_trace = try SignalTrace.init(self.allocator, target_id, wave_amplitude, target_node.phase);
                                    try self.traces.append(target_trace);

                                    try visited.put(target_id, true);
                                    try next_wave.append(try self.allocator.dupe(u8, target_id));
                                }
                            }
                        }
                    }
                }

                for (current_wave.items) |node_id| {
                    self.allocator.free(node_id);
                }
                current_wave.clearRetainingCapacity();

                for (next_wave.items) |node_id| {
                    try current_wave.append(try self.allocator.dupe(u8, node_id));
                }
            }
        }
    }

    pub fn getTraces(self: *const SignalPropagationEngine) []const SignalTrace {
        return self.traces.items;
    }

    pub fn clearTraces(self: *SignalPropagationEngine) void {
        for (self.traces.items) |*trace| {
            trace.deinit();
        }
        self.traces.clearRetainingCapacity();
    }

    pub fn updatePhases(self: *SignalPropagationEngine) !void {
        var node_iter = self.graph.nodes.iterator();
        while (node_iter.next()) |entry| {
            const node = entry.value_ptr;
            node.phase = @mod(node.phase + self.time_step, 2.0 * std.math.pi);
            const magnitude = node.quantum_state.magnitude();
            if (magnitude > 0.0) {
                const normalized_real = node.quantum_state.re / magnitude;
                const normalized_imag = node.quantum_state.im / magnitude;
                const rotated_real = normalized_real * @cos(self.time_step) - normalized_imag * @sin(self.time_step);
                const rotated_imag = normalized_real * @sin(self.time_step) + normalized_imag * @cos(self.time_step);
                node.quantum_state = nsir.Complex(f64).init(rotated_real * magnitude, rotated_imag * magnitude);
                try self.graph.setQuantumState(entry.key_ptr.*, node.quantum_state);
            }
        }
    }
};
