const std = @import("std");
const nsir = @import("nsir_core.zig");
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;

pub const QuantumBackendType = enum {
    simulator,
    ibm,
    rigetti,
};

pub const QuantumCircuit = struct {
    qubits: ArrayList([]const u8),
    gates: ArrayList(QuantumGate),
    allocator: Allocator,

    pub fn init(allocator: Allocator) QuantumCircuit {
        return QuantumCircuit{
            .qubits = ArrayList([]const u8).init(allocator),
            .gates = ArrayList(QuantumGate).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *QuantumCircuit) void {
        for (self.qubits.items) |qubit_id| {
            self.allocator.free(qubit_id);
        }
        self.qubits.deinit();
        for (self.gates.items) |*gate| {
            gate.deinit(self.allocator);
        }
        self.gates.deinit();
    }

    pub fn addQubit(self: *QuantumCircuit, qubit_id: []const u8) !void {
        const id = try self.allocator.dupe(u8, qubit_id);
        try self.qubits.append(id);
    }

    pub fn addGate(self: *QuantumCircuit, gate: QuantumGate) !void {
        try self.gates.append(gate);
    }
};

pub const QuantumGateType = enum {
    hadamard,
    pauli_x,
    pauli_y,
    pauli_z,
    cnot,
    phase,
};

pub const QuantumGate = struct {
    gate_type: QuantumGateType,
    target_qubits: ArrayList(usize),

    pub fn init(allocator: Allocator, gate_type: QuantumGateType) QuantumGate {
        return QuantumGate{
            .gate_type = gate_type,
            .target_qubits = ArrayList(usize).init(allocator),
        };
    }

    pub fn deinit(self: *QuantumGate, allocator: Allocator) void {
        _ = allocator;
        self.target_qubits.deinit();
    }

    pub fn addTarget(self: *QuantumGate, qubit_index: usize) !void {
        try self.target_qubits.append(qubit_index);
    }
};

pub const QuantumTaskAdapter = struct {
    allocator: Allocator,
    graph: *nsir.SelfSimilarRelationalGraph,
    backend_type: QuantumBackendType,
    prng: std.rand.DefaultPrng,

    pub fn init(allocator: Allocator, graph: *nsir.SelfSimilarRelationalGraph, backend: QuantumBackendType) QuantumTaskAdapter {
        const seed = @as(u64, @bitCast(std.time.milliTimestamp()));
        return QuantumTaskAdapter{
            .allocator = allocator,
            .graph = graph,
            .backend_type = backend,
            .prng = std.rand.DefaultPrng.init(seed),
        };
    }

    pub fn selectQuantumSubgraph(self: *QuantumTaskAdapter, min_entanglement_quality: f64) !ArrayList([]const u8) {
        var selected = ArrayList([]const u8).init(self.allocator);

        var edge_iter = self.graph.edges.iterator();
        while (edge_iter.next()) |entry| {
            for (entry.value_ptr.items) |edge| {
                if (edge.quality == .entangled and edge.correlationMagnitude() > min_entanglement_quality) {
                    var found_source = false;
                    var found_target = false;
                    for (selected.items) |node_id| {
                        if (std.mem.eql(u8, node_id, edge.source)) found_source = true;
                        if (std.mem.eql(u8, node_id, edge.target)) found_target = true;
                    }
                    if (!found_source) {
                        try selected.append(try self.allocator.dupe(u8, edge.source));
                    }
                    if (!found_target) {
                        try selected.append(try self.allocator.dupe(u8, edge.target));
                    }
                }
            }
        }

        return selected;
    }

    pub fn buildCircuit(self: *QuantumTaskAdapter, node_ids: []const []const u8) !QuantumCircuit {
        var circuit = QuantumCircuit.init(self.allocator);

        for (node_ids) |node_id| {
            try circuit.addQubit(node_id);
        }

        for (node_ids, 0..) |_, i| {
            var gate = QuantumGate.init(self.allocator, .hadamard);
            try gate.addTarget(i);
            try circuit.addGate(gate);
        }

        if (node_ids.len > 1) {
            var i: usize = 0;
            while (i < node_ids.len - 1) : (i += 1) {
                var gate = QuantumGate.init(self.allocator, .cnot);
                try gate.addTarget(i);
                try gate.addTarget(i + 1);
                try circuit.addGate(gate);
            }
        }

        return circuit;
    }

    pub fn executeCircuit(self: *QuantumTaskAdapter, circuit: *QuantumCircuit) !void {
        for (circuit.gates.items) |gate| {
            switch (gate.gate_type) {
                .hadamard => {
                    for (gate.target_qubits.items) |qubit_idx| {
                        if (qubit_idx < circuit.qubits.items.len) {
                            const node_id = circuit.qubits.items[qubit_idx];
                            self.graph.applyQuantumGate(node_id, nsir.hadamardGate);
                        }
                    }
                },
                .pauli_x => {
                    for (gate.target_qubits.items) |qubit_idx| {
                        if (qubit_idx < circuit.qubits.items.len) {
                            const node_id = circuit.qubits.items[qubit_idx];
                            self.graph.applyQuantumGate(node_id, nsir.pauliXGate);
                        }
                    }
                },
                .pauli_y => {
                    for (gate.target_qubits.items) |qubit_idx| {
                        if (qubit_idx < circuit.qubits.items.len) {
                            const node_id = circuit.qubits.items[qubit_idx];
                            self.graph.applyQuantumGate(node_id, nsir.pauliYGate);
                        }
                    }
                },
                .pauli_z => {
                    for (gate.target_qubits.items) |qubit_idx| {
                        if (qubit_idx < circuit.qubits.items.len) {
                            const node_id = circuit.qubits.items[qubit_idx];
                            self.graph.applyQuantumGate(node_id, nsir.pauliZGate);
                        }
                    }
                },
                .cnot => {
                    if (gate.target_qubits.items.len >= 2) {
                        const control_idx = gate.target_qubits.items[0];
                        const target_idx = gate.target_qubits.items[1];
                        if (control_idx < circuit.qubits.items.len and target_idx < circuit.qubits.items.len) {
                            const control_id = circuit.qubits.items[control_idx];
                            const target_id = circuit.qubits.items[target_idx];
                            try self.graph.entangleNodes(control_id, target_id);
                        }
                    }
                },
                .phase => {
                    for (gate.target_qubits.items) |qubit_idx| {
                        if (qubit_idx < circuit.qubits.items.len) {
                            const node_id = circuit.qubits.items[qubit_idx];
                            if (self.graph.getNode(node_id)) |node| {
                                node.phase = @mod(node.phase + std.math.pi / 4.0, 2.0 * std.math.pi);
                            }
                        }
                    }
                },
            }
        }
    }

    pub fn applyResults(self: *QuantumTaskAdapter, node_ids: []const []const u8) !void {
        for (node_ids) |node_id| {
            if (self.graph.getNode(node_id)) |node| {
                const measurement = self.prng.random().float(f64);
                const collapsed_state = if (measurement > 0.5) nsir.Complex(f64).init(1.0, 0.0) else nsir.Complex(f64).init(0.0, 1.0);
                node.quantum_state = collapsed_state;
                try self.graph.setQuantumState(node_id, collapsed_state);

                var edge_iter = self.graph.edges.iterator();
                while (edge_iter.next()) |entry| {
                    for (entry.value_ptr.items) |*edge| {
                        if (std.mem.eql(u8, edge.source, node_id) or std.mem.eql(u8, edge.target, node_id)) {
                            edge.quantum_correlation = collapsed_state;
                            if (edge.quality == .entangled) {
                                edge.quality = .collapsed;
                            }
                        }
                    }
                }
            }
        }
    }
};
