const std = @import("std");
const nsir = @import("nsir_core.zig");
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const AutoHashMap = std.AutoHashMap;
const StringHashMap = std.StringHashMap;

pub const MemoryBlock = struct {
    block_id: [16]u8,
    content_hash: [32]u8,
    data: []const u8,
    size: usize,
    surprise_score: f64,
    access_count: usize,
    last_access_time: i64,
    retention_priority: f64,
    allocator: Allocator,

    pub fn init(allocator: Allocator, block_id: [16]u8, data: []const u8) !MemoryBlock {
        var hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(data, &hash, .{});

        return MemoryBlock{
            .block_id = block_id,
            .content_hash = hash,
            .data = try allocator.dupe(u8, data),
            .size = data.len,
            .surprise_score = 1.0,
            .access_count = 1,
            .last_access_time = std.time.milliTimestamp(),
            .retention_priority = 1.0,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *MemoryBlock) void {
        self.allocator.free(self.data);
    }

    pub fn updateAccess(self: *MemoryBlock) void {
        self.access_count += 1;
        self.last_access_time = std.time.milliTimestamp();
        self.retention_priority = @as(f64, @floatFromInt(self.access_count)) * self.surprise_score;
    }
};

pub const SurpriseMemoryManager = struct {
    allocator: Allocator,
    graph: *nsir.SelfSimilarRelationalGraph,
    blocks: AutoHashMap([16]u8, MemoryBlock),
    surprise_threshold: f64,
    max_capacity: usize,
    current_size: usize,
    prng: std.rand.DefaultPrng,

    pub fn init(allocator: Allocator, graph: *nsir.SelfSimilarRelationalGraph, max_capacity: usize) SurpriseMemoryManager {
        const seed = @as(u64, @bitCast(std.time.milliTimestamp()));
        return SurpriseMemoryManager{
            .allocator = allocator,
            .graph = graph,
            .blocks = AutoHashMap([16]u8, MemoryBlock).init(allocator),
            .surprise_threshold = 0.3,
            .max_capacity = max_capacity,
            .current_size = 0,
            .prng = std.rand.DefaultPrng.init(seed),
        };
    }

    pub fn deinit(self: *SurpriseMemoryManager) void {
        var iter = self.blocks.valueIterator();
        while (iter.next()) |block| {
            block.deinit();
        }
        self.blocks.deinit();
    }

    pub fn setSurpriseThreshold(self: *SurpriseMemoryManager, threshold: f64) void {
        self.surprise_threshold = threshold;
    }

    pub fn computeSurprise(self: *SurpriseMemoryManager, new_data: []const u8) f64 {
        var new_hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(new_data, &new_hash, .{});

        var min_distance: f64 = 1.0;
        var iter = self.blocks.valueIterator();
        while (iter.next()) |block| {
            var distance: f64 = 0.0;
            for (block.content_hash, 0..) |byte, i| {
                const diff = @as(i16, byte) - @as(i16, new_hash[i]);
                distance += @as(f64, @floatFromInt(diff * diff));
            }
            distance = @sqrt(distance) / 256.0;
            if (distance < min_distance) {
                min_distance = distance;
            }
        }

        return min_distance;
    }

    pub fn storeIfSurprising(self: *SurpriseMemoryManager, data: []const u8) !bool {
        const surprise = self.computeSurprise(data);

        if (surprise < self.surprise_threshold) {
            return false;
        }

        if (self.current_size + data.len > self.max_capacity) {
            try self.evictLowPriority();
        }

        var block_id: [16]u8 = undefined;
        self.prng.random().bytes(&block_id);

        var block = try MemoryBlock.init(self.allocator, block_id, data);
        block.surprise_score = surprise;
        block.retention_priority = surprise;

        try self.blocks.put(block_id, block);
        self.current_size += data.len;

        const node_id = try std.fmt.allocPrint(self.allocator, "mem_{x}", .{block_id[0..8].*});
        defer self.allocator.free(node_id);

        var node = try nsir.Node.init(self.allocator, node_id, "memory", surprise, 0.0, 0.0);
        self.allocator.free(node.data);
        node.data = try self.allocator.dupe(u8, data);
        node.fractal_dimension = surprise;
        try self.graph.addNode(node);

        return true;
    }

    pub fn retrieve(self: *SurpriseMemoryManager, block_id: [16]u8) ?*MemoryBlock {
        if (self.blocks.getPtr(block_id)) |block| {
            block.updateAccess();
            return block;
        }
        return null;
    }

    fn evictLowPriority(self: *SurpriseMemoryManager) !void {
        var min_priority: f64 = std.math.inf(f64);
        var evict_id: ?[16]u8 = null;

        var iter = self.blocks.iterator();
        while (iter.next()) |entry| {
            if (entry.value_ptr.retention_priority < min_priority) {
                min_priority = entry.value_ptr.retention_priority;
                evict_id = entry.key_ptr.*;
            }
        }

        if (evict_id) |id| {
            if (self.blocks.fetchRemove(id)) |removed| {
                self.current_size -= removed.value.size;
                var block = removed.value;
                block.deinit();
            }
        }
    }

    pub fn getHighPriorityBlocks(self: *SurpriseMemoryManager, count: usize) !ArrayList([16]u8) {
        var result = ArrayList([16]u8).init(self.allocator);

        var priorities = ArrayList(struct { id: [16]u8, priority: f64 }).init(self.allocator);
        defer priorities.deinit();

        var iter = self.blocks.iterator();
        while (iter.next()) |entry| {
            try priorities.append(.{ .id = entry.key_ptr.*, .priority = entry.value_ptr.retention_priority });
        }

        std.mem.sort(@TypeOf(priorities.items[0]), priorities.items, {}, struct {
            fn lessThan(_: void, a: @TypeOf(priorities.items[0]), b: @TypeOf(priorities.items[0])) bool {
                return a.priority > b.priority;
            }
        }.lessThan);

        const limit = @min(count, priorities.items.len);
        var i: usize = 0;
        while (i < limit) : (i += 1) {
            try result.append(priorities.items[i].id);
        }

        return result;
    }
};
