const std = @import("std");
const nsir = @import("nsir_core.zig");
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const StringHashMap = std.StringHashMap;

pub const ResearchPhase = enum {
    hypothesis,
    method,
    experiment,
    analysis,
    conclusion,
};

pub const ResearchTask = struct {
    task_id: []const u8,
    phase: ResearchPhase,
    hypothesis_node: ?[]const u8,
    method_node: ?[]const u8,
    dataset_descriptor: ?[]const u8,
    result_node: ?[]const u8,
    metrics: StringHashMap(f64),
    allocator: Allocator,

    pub fn init(allocator: Allocator, task_id: []const u8, phase: ResearchPhase) !ResearchTask {
        return ResearchTask{
            .task_id = try allocator.dupe(u8, task_id),
            .phase = phase,
            .hypothesis_node = null,
            .method_node = null,
            .dataset_descriptor = null,
            .result_node = null,
            .metrics = StringHashMap(f64).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *ResearchTask) void {
        self.allocator.free(self.task_id);
        if (self.hypothesis_node) |h| self.allocator.free(h);
        if (self.method_node) |m| self.allocator.free(m);
        if (self.dataset_descriptor) |d| self.allocator.free(d);
        if (self.result_node) |r| self.allocator.free(r);
        var iter = self.metrics.keyIterator();
        while (iter.next()) |key| {
            self.allocator.free(key.*);
        }
        self.metrics.deinit();
    }

    pub fn setHypothesis(self: *ResearchTask, node_id: []const u8) !void {
        if (self.hypothesis_node) |h| self.allocator.free(h);
        self.hypothesis_node = try self.allocator.dupe(u8, node_id);
    }

    pub fn setMethod(self: *ResearchTask, node_id: []const u8) !void {
        if (self.method_node) |m| self.allocator.free(m);
        self.method_node = try self.allocator.dupe(u8, node_id);
    }

    pub fn setResult(self: *ResearchTask, node_id: []const u8) !void {
        if (self.result_node) |r| self.allocator.free(r);
        self.result_node = try self.allocator.dupe(u8, node_id);
    }

    pub fn addMetric(self: *ResearchTask, name: []const u8, value: f64) !void {
        const key = try self.allocator.dupe(u8, name);
        try self.metrics.put(key, value);
    }
};

pub const ResearchHistory = struct {
    entries: ArrayList(ResearchTask),
    allocator: Allocator,

    pub fn init(allocator: Allocator) ResearchHistory {
        return ResearchHistory{
            .entries = ArrayList(ResearchTask).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *ResearchHistory) void {
        for (self.entries.items) |*entry| {
            entry.deinit();
        }
        self.entries.deinit();
    }

    pub fn addEntry(self: *ResearchHistory, task: ResearchTask) !void {
        try self.entries.append(task);
    }

    pub fn getLatest(self: *const ResearchHistory, count: usize) []const ResearchTask {
        const start = if (self.entries.items.len > count) self.entries.items.len - count else 0;
        return self.entries.items[start..];
    }
};

pub const ResearchAgentKernel = struct {
    allocator: Allocator,
    graph: *nsir.SelfSimilarRelationalGraph,
    history: ResearchHistory,
    current_tasks: ArrayList(ResearchTask),
    max_concurrent_tasks: usize,
    prng: std.rand.DefaultPrng,

    pub fn init(allocator: Allocator, graph: *nsir.SelfSimilarRelationalGraph) ResearchAgentKernel {
        const seed = @as(u64, @bitCast(std.time.milliTimestamp()));
        return ResearchAgentKernel{
            .allocator = allocator,
            .graph = graph,
            .history = ResearchHistory.init(allocator),
            .current_tasks = ArrayList(ResearchTask).init(allocator),
            .max_concurrent_tasks = 5,
            .prng = std.rand.DefaultPrng.init(seed),
        };
    }

    pub fn deinit(self: *ResearchAgentKernel) void {
        self.history.deinit();
        for (self.current_tasks.items) |*task| {
            task.deinit();
        }
        self.current_tasks.deinit();
    }

    pub fn createTask(self: *ResearchAgentKernel, task_id: []const u8, phase: ResearchPhase) !void {
        if (self.current_tasks.items.len >= self.max_concurrent_tasks) {
            return error.TooManyTasks;
        }

        const task = try ResearchTask.init(self.allocator, task_id, phase);
        try self.current_tasks.append(task);
    }

    pub fn executeTaskPhase(self: *ResearchAgentKernel, task_index: usize) !void {
        if (task_index >= self.current_tasks.items.len) return error.InvalidTaskIndex;

        var task = &self.current_tasks.items[task_index];

        switch (task.phase) {
            .hypothesis => try self.generateHypothesis(task),
            .method => try self.designMethod(task),
            .experiment => try self.runExperiment(task),
            .analysis => try self.analyzeResults(task),
            .conclusion => try self.drawConclusion(task),
        }
    }

    fn generateHypothesis(self: *ResearchAgentKernel, task: *ResearchTask) !void {
        const hyp_id = try std.fmt.allocPrint(self.allocator, "hyp_{s}_{d}", .{ task.task_id, std.time.milliTimestamp() });
        defer self.allocator.free(hyp_id);

        var node = try nsir.Node.init(self.allocator, hyp_id, "hypothesis", 1.0, 0.0, 0.0);
        self.allocator.free(node.data);
        node.data = try std.fmt.allocPrint(self.allocator, "Hypothesis for task {s}", .{task.task_id});
        node.fractal_dimension = 1.5;
        try self.graph.addNode(node);

        try task.setHypothesis(hyp_id);
        task.phase = .method;
    }

    fn designMethod(self: *ResearchAgentKernel, task: *ResearchTask) !void {
        const method_id = try std.fmt.allocPrint(self.allocator, "method_{s}_{d}", .{ task.task_id, std.time.milliTimestamp() });
        defer self.allocator.free(method_id);

        var node = try nsir.Node.init(self.allocator, method_id, "method", 0.8, 0.2, std.math.pi / 4.0);
        self.allocator.free(node.data);
        node.data = try std.fmt.allocPrint(self.allocator, "Method for task {s}", .{task.task_id});
        try self.graph.addNode(node);

        try task.setMethod(method_id);

        if (task.hypothesis_node) |hyp| {
            const edge = try nsir.Edge.init(self.allocator, hyp, method_id, .coherent, 0.9, 0.5, 0.5, 1.0);
            try self.graph.addEdge(edge);
        }

        task.phase = .experiment;
    }

    fn runExperiment(self: *ResearchAgentKernel, task: *ResearchTask) !void {
        const result_id = try std.fmt.allocPrint(self.allocator, "result_{s}_{d}", .{ task.task_id, std.time.milliTimestamp() });
        defer self.allocator.free(result_id);

        const accuracy = 0.5 + self.prng.random().float(f64) * 0.5;
        const loss = self.prng.random().float(f64) * 0.5;

        var node = try nsir.Node.init(self.allocator, result_id, "result", accuracy, loss, std.math.pi / 2.0);
        self.allocator.free(node.data);
        node.data = try std.fmt.allocPrint(self.allocator, "Experimental result: accuracy={d:.3}, loss={d:.3}", .{ accuracy, loss });
        try self.graph.addNode(node);

        try task.setResult(result_id);
        try task.addMetric("accuracy", accuracy);
        try task.addMetric("loss", loss);

        if (task.method_node) |method| {
            const edge = try nsir.Edge.init(self.allocator, method, result_id, .coherent, 0.95, accuracy, loss, 1.2);
            try self.graph.addEdge(edge);
        }

        task.phase = .analysis;
    }

    fn analyzeResults(self: *ResearchAgentKernel, task: *ResearchTask) !void {
        if (task.result_node) |result_id| {
            if (self.graph.getNode(result_id)) |node| {
                const quality = node.quantum_state.magnitude();

                const analysis_id = try std.fmt.allocPrint(self.allocator, "analysis_{s}_{d}", .{ task.task_id, std.time.milliTimestamp() });
                defer self.allocator.free(analysis_id);

                var analysis_node = try nsir.Node.init(self.allocator, analysis_id, "analysis", quality, 0.0, std.math.pi);
                self.allocator.free(analysis_node.data);
                analysis_node.data = try std.fmt.allocPrint(self.allocator, "Analysis: quality score={d:.3}", .{quality});
                try self.graph.addNode(analysis_node);

                const edge = try nsir.Edge.init(self.allocator, result_id, analysis_id, .fractal, quality, quality, 0.0, 1.5);
                try self.graph.addEdge(edge);
            }
        }

        task.phase = .conclusion;
    }

    fn drawConclusion(self: *ResearchAgentKernel, task: *ResearchTask) !void {
        const conclusion_id = try std.fmt.allocPrint(self.allocator, "conclusion_{s}_{d}", .{ task.task_id, std.time.milliTimestamp() });
        defer self.allocator.free(conclusion_id);

        const success_score = if (task.metrics.get("accuracy")) |acc| acc else 0.5;

        var node = try nsir.Node.init(self.allocator, conclusion_id, "conclusion", success_score, 0.0, 2.0 * std.math.pi);
        self.allocator.free(node.data);
        node.data = try std.fmt.allocPrint(self.allocator, "Conclusion: success={d:.3}", .{success_score});
        node.fractal_dimension = 2.0;
        try self.graph.addNode(node);

        if (task.hypothesis_node) |hyp| {
            const edge = try nsir.Edge.init(self.allocator, hyp, conclusion_id, .collapsed, success_score, success_score, 0.0, 2.0);
            try self.graph.addEdge(edge);
        }

        try self.history.addEntry(task.*);
    }

    pub fn completeTask(self: *ResearchAgentKernel, task_index: usize) !void {
        if (task_index >= self.current_tasks.items.len) return error.InvalidTaskIndex;

        _ = self.current_tasks.orderedRemove(task_index);
    }

    pub fn getActiveTaskCount(self: *const ResearchAgentKernel) usize {
        return self.current_tasks.items.len;
    }

    pub fn getHistorySize(self: *const ResearchAgentKernel) usize {
        return self.history.entries.items.len;
    }
};
